# Exact transitive constructor-function closure from supplied family.py.
PARAMETER_SOURCE="from math import gcd as integer_gcd,isqrt\nfrom functools import lru_cache\nfrom fractions import Fraction as F\n\ndef is_prime(n):\n return n>=2 and(n==2 or(n%2 and all((n%d for d in range(3,isqrt(n)+1,2)))))\n\n@lru_cache(None)\ndef prime_at_least(n):\n n=max(3,n)\n if n%2==0:\n  n+=1\n while not is_prime(n):\n  n+=2\n return n\n\ndef ceil_log2(n):\n return(n-1).bit_length()if n>1 else 0\n\ndef root(n,d):\n if n<0 or d<1:\n  raise ValueError('nonnegative radicand, positive root')\n if n<2:\n  return n\n exponent=n.bit_length()-1\n if n==(1<<exponent)and exponent%d==0:\n  return 1<<(exponent//d)\n lo=0;hi=1<<(n.bit_length()+d-1)//d\n while lo+1<hi:\n  mid=(lo+hi)//2\n  if mid**d<=n:\n   lo=mid\n  else:\n   hi=mid\n return lo\n\ndef ceil_root(n,d):\n a=root(n,d);return a+(a**d<n)\n\ndef rational(numerator,denominator):\n divisor=integer_gcd(numerator,denominator);return numerator//divisor,denominator//divisor\n\ndef valid_mode(n,mode):\n if type(n)is not int or n<1 or type(mode)is not tuple or len(mode)!=2:return False\n p,q=mode\n return(type(p)is int and type(q)is int and p>0 and q>0\n and(3*q<=20*p and 100*p<=53*q)and max(p,q)<=100*ceil_log2(n+1))\n\n@lru_cache(None)\ndef regime(mode):\n if type(mode)is not tuple or len(mode)!=2:raise ValueError('rational rate')\n p,q=mode\n if type(p)is not int or type(q)is not int or p<1 or q<1 or not(3*q<=20*p and 100*p<=53*q):\n  raise ValueError('rate outside3/20..53/100')\n an=q;ad=q-p;sn=11*ad*q+10*an*p;sd=10*ad*q;cn=9999*(q-p)*sd;cd=10000*q*sn\n return dict(beta=rational(p,q),alpha=rational(an,ad),\n zeta=rational(1000000*p-2*q,2000000*q),\n group=rational(q-p,q),slice=rational(2000000*p-q,2000000*q),\n seed_guard=rational(sn,sd),arity=rational(cn,cd))\n\ndef field_cap(mode):\n p,q=mode\n if 100*p<=19*q:return 2\n if 10*p<=3*q:return 3\n if 5*p<=2*q:return 4\n if 25*p<=12*q:return 5\n return 6\n\n@lru_cache(None)\ndef optimal_parameters(n,K,mode=(1,2),take=None):\n if not valid_mode(n,mode):return None\n if not 2<=K<=n:\n  return None\n L=ceil_log2(n+1);w=K.bit_length()-1;bn,bd=regime(mode)['beta'];an,ad=regime(mode)['alpha'];m=root(K**bn,bd)//(L+1)**12\n if m<1:return None\n if take is not None:\n  if type(take)is not int or not 1<=take<=m:return None\n  m=take\n d=(an*L+ad*w-1)//(ad*w);h=d*ceil_root(n,d)+1;bound=(1<<30)*h*d*(32*m);s=prime_at_least(bound.bit_length())\n while s<=(L+1)**2 and(1<<s)<=bound*s:\n  s=prime_at_least(s+1)\n q=1<<s\n if s>(L+1)**2:\n  return None\n Q=q**d\n if Q>(n+1)**field_cap(mode)or h**d>(n+1)**field_cap(mode):\n  return None\n if q<=(1<<30)*h*d*s*(32*m) or h>=q-1 or m>=Q:\n  return None\n if K<400*m*h*d*s*s+ceil_log2(32*m)+3:\n  return None\n return(m,s,d,h,(d+1)*s)\n\ndef response_parameters(n,K,take,mode=(1,2)):\n if not valid_mode(n,mode)or type(K)is not int or not 2<=K<=n or type(take)is not int or not 1<=take<=K:return None\n p,q=regime(mode)['beta'];retuned=max(2,ceil_root((take*(ceil_log2(n+1)+1)**12)**q,p))\n if retuned>K:return None\n return optimal_parameters(n,retuned,mode=mode,take=take)\n\nRANGES=((F(1,10),F(1,5)),(F(2,5),F(7,10)),(F(13,10),F(2)),(F(12,5),F(17,5)),(F(1,4),F(3,5)),(F(1,5),F(7,20)))\n\ndef analytic_prefilter(config):\n if len(config)!=6:return False\n h,a,wm,w0,gap,confidence=config\n return(all(lo<=value<=hi for value,(lo,hi)in zip(config,RANGES))\n and a/wm<F(53,100)and a/w0>F(3,20)\n and 2*wm>w0+gap\n and confidence<a/2-F(102,100000000)*w0\n )\n\nconstant_parameters=optimal_parameters\n"
assert sha256(PARAMETER_SOURCE.encode()).hexdigest()=='a1791d6549d9b4fe3bc7fcc7fab3be9f413b3437c4de45254e70145c37e0db13'
f=ModuleType('candidate_parameters')
exec(compile(PARAMETER_SOURCE,'candidate_parameters.py','exec'),f.__dict__)
def midpoint_certificate():
 from math import isqrt
 a=F(6249,10000);D=F(111863,40000);wm=D/2+F(1,10**6);w0=F(25419,10000);X=D-w0;h=F(119340301699,10**12)
 pc=a/2-F(102,10**8)*w0-F(1,10**13);assert f.analytic_prefilter((h,a,wm,w0,X,pc))and D==w0+X<F(139829,50000)
 M=262144;scale=10**15;yscale=18*10**12;step=(w0-wm)/M
 V=lcm(wm.denominator,(step/2).denominator,D.denominator);U0=int((wm+step/2)*V);inc=int(step*V);dn=int(D*V);ap,aq=a.numerator,a.denominator
 assert inc%2==0 and F(U0,V)==wm+step/2 and F(inc,V)==step
 total=0;right=[];cross=0
 for j in range(M):
  U=U0+j*inc;z=U*aq-ap*V;num=scale*z*z;den=aq*aq*U*V;q=num//den;assert q*den<=num<(q+1)*den;total+=q
  U+=inc//2;z=U*aq-ap*V;nr=scale*z*z;dr=aq*aq*U*V;upper=nr//dr+1;assert(upper-1)*dr<=nr<upper*dr;right.append(upper)
  if j in(0,1,M//2,M-1):
   for pos,value in[(U-inc//2,q),(U,upper-1)]:
    w=F(pos,V);beta=a/w;alpha=1/(1-beta);exact=scale*w*(1-beta)/(1+alpha*beta);assert value==exact.numerator//exact.denominator
   cross+=1
 assert total==242318959769412276707 and sum(right)==242319468752867876256
 suffix=sum(right);A=216*h.denominator*step.denominator*scale;B=864*h.numerator*step.numerator;Jsum=0;branches=[0,0,0]
 for j in range(M):
  rn=max(0,109*h.denominator*step.denominator*scale-B*suffix)
  if rn==0:y=0;branches[0]+=1
  elif 54*rn<=A:
   nr=6*rn*yscale;y=nr//A;assert y*A<=nr<(y+1)*A;branches[1]+=1
  else:
   nr=(216*rn-A)*yscale**2;dr=108*A;sq=isqrt(nr//dr);assert sq*sq*dr<=nr<(sq+1)**2*dr;y=sq-yscale//18;branches[2]+=1
  assert y>=0
  U=U0+j*inc-inc//2;gap=dn-U;num=scale*y*V*V;den=yscale*gap*gap;assert den>0;q=num//den;assert q*den<=num<(q+1)*den;Jsum+=q;suffix-=right[j]
 assert suffix==0 and Jsum==549999513468646731662
 ratio=F(864,109)*h*step*F(total,scale);confidence=2*h*(F(17,18)/X-step*F(Jsum,scale))
 assert ratio==F(1785857496442746346634861447341648444053,1785856000000000000000000000000000000000)>1
 assert confidence==F(3754643731142310263976092824071804383363479,12017074176000000000000000000000000000000000)<pc
 W=w0-wm;mu=ratio-1-8*h*W/10**12;assert mu>0;target=176*h*W*W/mu;J=1+-(-target.numerator//target.denominator)
 assert ratio-8*h*W/10**12-88*h*W*W/J>1+mu/2>1
 return dict(terms=M,total=str(total),right=str(sum(right)),Jsum=str(Jsum),crosschecks=cross,left_mesh=str(J),branches=branches)

def parameter_certificate():
 n=1<<16384;K=1<<1024;take=1<<160;mode=(2,5);L=f.ceil_log2(n+1)
 cp=f.constant_parameters(n,K,mode=mode);rp=f.response_parameters(n,K,take,mode=mode)
 assert cp is not None and rp is not None and rp[0]==take
 retuned=max(2,f.ceil_root((take*(L+1)**12)**5,2));assert retuned<K
 assert(retuned-1)**2<(take*(L+1)**12)**5<=retuned**2
 def entropy(c):
  m,s,d,h,_=c;assert(1<<s)>(1<<30)*h*d*s*(32*m)
  return 400*m*h*d*s*s+f.ceil_log2(32*m)+3
 td,tr=entropy(cp),entropy(rp);assert td<K and tr<=retuned and tr<(1<<700)
 sn,sd=f.regime(mode)['seed_guard']
 for c in(cp,rp):assert c[-1]*sd<sn*f.ceil_log2(n)
 return dict(n_log2=16384,K_log2=1024,take_log2=160,default_entropy_bits=td.bit_length(),response_entropy_bits=tr.bit_length(),retuned_bits=retuned.bit_length(),default_seed=cp[-1],response_seed=rp[-1],passed=True)

import base64,struct,time,zlib,itertools
COVER_SOURCE='{"version":1,"encoding":"zlib-base64-terminal-covers-v1","data":""}\n'
def terminal_cover_audit():
    started=time.monotonic()
    n,d=8,3
    legal=[a for a in range(256) if not(a&1 and a&4)
           and not(a&2 and a&8) and not(a&16 and a&32)]
    legal_set=set(legal);index={v:i for i,v in enumerate(legal)};planes=[]
    def extend(offset,points,pivots,low):
        if len(pivots)==d:
            planes.append(tuple(index[v] for v in points));return
        k=len(pivots)
        for pivot in range(low,n-(d-k)+1):
            if offset>>pivot&1:continue
            free=[j for j in range(pivot) if j not in pivots]
            for bits in range(1<<len(free)):
                v=(1<<pivot)|sum(((bits>>j)&1)<<b for j,b in enumerate(free))
                more=[x^v for x in points]
                if all(x in legal_set for x in more):
                    extend(offset,points+more,pivots+[pivot],pivot+1)
    for a in legal:extend(a,[a],[],0)
    assert len(legal)==108 and len(planes)==14391
    def trees(labels):
        if len(labels)==1:return [labels[0]]
        out=[];first=labels[0];rest=labels[1:]
        for k in range(len(rest)):
            for more in itertools.combinations(rest,k):
                left=(first,)+more;right=tuple(x for x in labels if x not in left)
                for a in trees(left):
                    for b in trees(right):out.append((a,b))
        return out
    def serial(tree,perm):
        if isinstance(tree,int):return str(perm[tree])
        a,b=serial(tree[0],perm),serial(tree[1],perm)
        return '('+','.join(sorted((a,b)))+')'
    permutations=[]
    for a,b,e in itertools.product((0,1),repeat=3):
        p=list(range(7))
        if a:p[1],p[2]=p[2],p[1]
        if b:p[3],p[4]=p[4],p[3]
        if e:p[5],p[6]=p[6],p[5]
        permutations.append(p)
    all_trees=trees(tuple(range(7)));seen=set();representatives=[]
    for tree in all_trees:
        key=min(serial(tree,p) for p in permutations)
        if key not in seen:seen.add(key);representatives.append(tree)
    assert len(all_trees)==10395 and len(representatives)==1710
    certificate=json.loads(COVER_SOURCE)
    assert set(certificate)=={'version','encoding','data'}
    assert certificate['version']==1 and certificate['encoding']=='zlib-base64-terminal-covers-v1'
    compressed=base64.b64decode(certificate['data'],validate=True)
    decoder=zlib.decompressobj();raw=decoder.decompress(compressed,200000)
    assert decoder.eof and not decoder.unused_data and not decoder.unconsumed_tail
    assert raw[:4]==b'TC61' and struct.unpack_from('<H',raw,4)[0]==1710
    covers=[];pos=6
    for _ in representatives:
        count=raw[pos];pos+=1
        assert 1<=count<=255
        ids=list(struct.unpack_from('<'+'H'*count,raw,pos));pos+=2*count
        assert all(0<=i<len(planes) for i in ids)
        covers.append(ids)
    assert pos==len(raw)
    assignments=64*3**6;full=(1<<assignments)-1
    repeat=full//((1<<64)-1)
    signs=[sum(((j>>i)&1)<<j for j in range(64))*repeat for i in range(6)]
    op_masks=[]
    for i in range(6):
        stride=64*3**i
        a=(full//((1<<(3*stride))-1))*((1<<stride)-1)
        op_masks.append((a,a<<stride,a<<(2*stride)))
    total_planes=0
    for tree,ids in zip(representatives,covers):
        operations=[]
        def compile_tree(t):
            if isinstance(t,int):return t
            a,b=compile_tree(t[0]),compile_tree(t[1])
            operations.append((a,b));return 6+len(operations)
        root=compile_tree(tree);assert root==12 and len(operations)==6
        points={j for pi in ids for j in planes[pi]};values={}
        for j in points:
            a=legal[j]
            leaves=[signs[i] if not(a>>i&1) else full^signs[i] for i in range(6)]
            leaves.extend(full if a>>i&1 else 0 for i in (6,7))
            v=[leaves[0]&leaves[1]]+leaves[2:]
            for (left,right),(aa,oo,xx) in zip(operations,op_masks):
                x,y=v[left],v[right]
                v.append(((x&y)&aa)|((x|y)&oo)|((x^y)&xx))
            values[j]=v[root]
        covered=0
        for pi in ids:
            zero=one=full
            for j in planes[pi]:
                one &= values[j];zero &= full^values[j]
            covered |= zero|one
        assert covered==full
        total_planes +=len(ids)
    return {'passed':True,'labeled_component_trees':10395,'shape_orbits':1710,
            'domain_points':108,'affine_three_flats':14391,
            'normalized_assignments_per_shape':assignments,
            'normalized_assignments_verified':assignments*len(representatives),
            'cover_plane_witnesses':total_planes,'certificate_raw_bytes':len(raw),
            'elapsed_seconds':time.monotonic()-started}
def run():
 r=midpoint_certificate();assert r['left_mesh']=='32782626'and r['branches']==[2,19260,242882]
 return dict(all_passed=True,midpoint=r,parameters=parameter_certificate(),gate_cover=terminal_cover_audit(),scope='Exact energy/confidence mesh and two parameter-only SU constructor cases. Complete normalized terminal read-once formula cover also executed. No field table, raw extractor output or accepted tree executed. Universal reductions are supplied.')
if __name__=='__main__':
 request=json.loads(input())
 if request!={}:raise ValueError('empty object required')
 print(json.dumps(run(),sort_keys=True))
